import math
import numpy as np
_erf = np.vectorize(math.erf, otypes=[float])
def ncdf(x):
    return 0.5 * (1 + _erf(np.asarray(x, dtype=float) / math.sqrt(2)))
def bs_price(S, K, r, T, sigma, kinds):
    K = np.asarray(K, dtype=float); sigma = np.asarray(sigma, dtype=float)
    sd = sigma * math.sqrt(T)
    d1 = (np.log(S / K) + (r + sigma ** 2 / 2) * T) / sd
    d2 = d1 - sd
    call = S * ncdf(d1) - K * math.exp(-r * T) * ncdf(d2)
    put = K * math.exp(-r * T) * ncdf(-d2) - S * ncdf(-d1)
    return np.where(np.asarray(kinds) == 'c', call, put)
def bs_vega(S, K, r, T, sigma):
    K = np.asarray(K, dtype=float); sigma = np.asarray(sigma, dtype=float)
    d1 = (np.log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * math.sqrt(T))
    return S * math.sqrt(T) * np.exp(-d1 ** 2 / 2) / math.sqrt(2 * math.pi)
